/**
 * An icon button with an on/off state (D150, spec/02 §1.5): SbIconButton's 48 dp, fills and focus ring; off [icon] (the
 * outline) in textMuted, text under hover and press; on [checkedIcon] (the filled form) in link, so the state shows
 * beyond colour; disabled the icon of the state in textSubtle. [label] names the thing („Licht“); the target is
 * toggleable with Role.Switch, so TalkBack says the name, the role and the state (on, off), and a press calls
 * [onCheckedChange] with the other state.
 */
@Composable
fun SbIconToggle(
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    label: String,
    icon: ImageVector,
    checkedIcon: ImageVector,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val shape = RoundedCornerShape(t.radius.control)
    Box(
        modifier
            .sbFocusRing(interaction, t.radius.control)
            .size(t.size.targetTouch)
            .clip(shape)
            .background(
                when {
                    !enabled -> Color.Transparent
                    pressed -> c.pressedFill
                    hovered -> c.hoverFill
                    else -> Color.Transparent
                },
                shape,
            )
            .toggleable(
                value = checked,
                interactionSource = interaction,
                indication = null,
                enabled = enabled,
                role = Role.Switch,
                onValueChange = onCheckedChange,
            ),
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            if (checked) checkedIcon else icon,
            contentDescription = label,
            tint = when {
                !enabled -> c.textSubtle
                checked -> c.link
                pressed || hovered -> c.text
                else -> c.textMuted
            },
            modifier = Modifier.size(t.size.iconLg),
        )
    }
}
